ID_12=$(need /networkServices 'ICMP_ANY' 12)
cat > "$OUT/13.json" <<FWSHIFT_JSON
{"name": "fws-Infra", "destTcpPorts": [{"start": 53}], "destUdpPorts": [{"start": 53}, {"start": 123}], "type": "CUSTOM", "description": "FWShift"}
FWSHIFT_JSON
ID_13=$(create /networkServices 'fws-Infra' "$OUT/13.json" 13)
ID_14=$(need /networkServices 'GRE_PROTOCOL' 14)
ID_15=$(need /networkServices 'ESP_PROTOCOL' 15)
ID_16=$(need /networkServices 'TCP_ANY' 16)
