ID_19=$(need /locations 'Guest-WiFi' 19)

# Firewall filtering rules, from order 1 on, in the order of the converted policy.
cat > "$OUT/20.json" <<FWSHIFT_JSON
{"name": "fws-Allow DNS to resolvers", "order": 1, "rank": 7, "action": "ALLOW", "state": "ENABLED", "locations": [{"id": ${ID_1}}], "srcIpGroups": [{"id": ${ID_2}}], "destAddresses": ["198.51.100.53"], "nwServices": [{"id": ${ID_3}}]}
FWSHIFT_JSON
ID_20=$(create /firewallFilteringRules 'fws-Allow DNS to resolvers' "$OUT/20.json" 20)
cat > "$OUT/21.json" <<FWSHIFT_JSON
{"name": "fws-Block SSH out", "order": 2, "rank": 7, "action": "BLOCK_RESET", "state": "ENABLED", "nwServices": [{"id": ${ID_4}}]}
FWSHIFT_JSON
ID_21=$(create /firewallFilteringRules 'fws-Block SSH out' "$OUT/21.json" 21)
cat > "$OUT/22.json" <<FWSHIFT_JSON
{"name": "fws-Partner app", "order": 3, "rank": 7, "action": "ALLOW", "state": "ENABLED", "locations": [{"id": ${ID_5}}], "srcIps": ["10.10.20.0/24"], "destAddresses": ["198.51.100.0/25", "203.0.113.50"], "nwServices": [{"id": ${ID_6}}]}
FWSHIFT_JSON
ID_22=$(create /firewallFilteringRules 'fws-Partner app' "$OUT/22.json" 22)
cat > "$OUT/23.json" <<FWSHIFT_JSON
{"name": "fws-Branch web", "order": 4, "rank": 7, "action": "ALLOW", "state": "DISABLED", "description": "FWSHIFT inactive, see the report. branches browse during work hours", "locations": [{"id": ${ID_7}}], "nwServices": [{"id": ${ID_8}}]}
FWSHIFT_JSON
ID_23=$(create /firewallFilteringRules 'fws-Branch web' "$OUT/23.json" 23)
cat > "$OUT/24.json" <<FWSHIFT_JSON
{"name": "fws-Engineers to SaaS", "order": 5, "rank": 7, "action": "ALLOW", "state": "DISABLED", "description": "FWSHIFT inactive, see the report.", "destAddresses": ["192.0.0.8"], "nwServices": [{"id": ${ID_9}}]}
