cat > "$OUT/25.json" <<FWSHIFT_JSON
{"name": "fws-No embargoed countries", "order": 6, "rank": 7, "action": "BLOCK_DROP", "state": "DISABLED", "description": "FWSHIFT inactive, see the report."}
