{"name": "fws-Printers syslog", "order": 7, "rank": 7, "action": "ALLOW", "state": "ENABLED", "srcIpGroups": [{"id": ${ID_10}}], "destAddresses": ["192.0.2.10-192.0.2.20"], "nwServices": [{"id": ${ID_11}}]}
