ID_26=$(create /firewallFilteringRules 'fws-Printers syslog' "$OUT/26.json" 26)
cat > "$OUT/27.json" <<FWSHIFT_JSON
{"name": "fws-Infra out", "order": 8, "rank": 7, "action": "ALLOW", "state": "DISABLED", "nwServices": [{"id": ${ID_12}}, {"id": ${ID_13}}]}
